<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/ui_components.php';
$flowDevices=recoveryUiDevices($pdo);
$config=require __DIR__.'/../config/commerce.php';$currentPage='commerce';
$rows=$pdo->query('SELECT l.*,d.serial_number FROM recovery_commerce_listings l JOIN recovery_devices d ON d.id=l.recovery_device_id ORDER BY l.id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
$sales=$pdo->query('SELECT s.order_id,s.status,d.serial_number FROM recovery_commerce_sales s JOIN recovery_commerce_listings l ON l.variant_id=s.variant_id AND l.provider=s.provider JOIN recovery_devices d ON d.id=l.recovery_device_id ORDER BY s.id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
function commerceEscape(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Commerce · Recovery Hub</title><link rel="stylesheet" href="/assets/css/erp-theme-v5.css"></head><body class="recovery-app"><?php require __DIR__.'/../includes/header.php';?>
<main class="page workflow-page reference-flow"><div class="breadcrumb"><a href="/index.php">Recovery</a><span>›</span><a href="/pages/inventory.php">Recovery Inventory</a><span>›</span>Export to Commerce</div><div class="page-header"><div><h1 class="page-title">Export to Whatnot (Shopify)</h1><p class="page-description">Manage serialized listings, paid sales and physical scan-out.</p></div></div><?php recoveryUiSteps(['Select inventory','Listing details','Review & Export','Complete']); recoveryUiSelection($flowDevices,'REC_WHATNOT'); ?><p class="notice"><?= $config['local']?'Local simulation — uses the copied ERP and creates no Shopify products or real orders.':'Shopify connector — exports one reserved serial as a draft product. Review its condition and publish through Shopify.' ?></p>
<p>Export reserves the ERP device. A paid order does not remove stock. Scan the physical location and serial to confirm the sale and record net recovery.</p>
<section class="card workflow-card flow-configuration"><h2>Listing Configuration</h2><form id="commerce" class="workflow-form"><label>Action <select id="action"><option value="export">Export serialized device</option><?php if($config['local']):?><option value="simulate-paid">Simulate paid sale locally</option><?php endif;?><option value="scan-out">Confirm paid order / serial scan-out</option></select></label>
<label>Scan serial <input id="serial" required autocomplete="off"></label>
<div id="exportFields"><label>Price (USD) <input id="price" type="number" min="0.01" step="0.01"></label></div>
<div id="exitFields" hidden><label>Order ID <input id="order" placeholder="gid://shopify/Order/123"></label><label>Scan current Retail Eligible location <input id="location" autocomplete="off"></label><label>Confirmed direct costs (USD) <input id="costs" type="number" min="0" step="0.01" placeholder="Enter 0 if none"></label></div>
<button class="btn-primary" id="submit">Process serial</button></form><aside class="listing-preview"><h3>Listing Preview</h3><div class="listing-device-placeholder" aria-hidden="true">▣</div><strong id="listingPreviewTitle">Select a Recovery device</strong><div id="listingPreviewPrice" class="preview-price">—</div><p>One reserved serial per Shopify draft. Review the actual condition and photos in Shopify before publishing.</p><dl class="summary-list"><dt>Serialized units</dt><dd id="listingPreviewUnits">1</dd><dt>Inventory per listing</dt><dd>1</dd><dt>Publication</dt><dd>Draft</dd></dl></aside></section><p id="message" role="status"></p>
<section class="card workflow-card"><h2>Exported serials</h2><div class="scroll"><table><tr><th>Serial</th><th>Provider</th><th>State</th><th>Variant</th></tr><?php foreach($rows as $row):?><tr><?php foreach(['serial_number','provider','state','variant_id'] as $field):?><td><?= commerceEscape($row[$field]) ?></td><?php endforeach;?></tr><?php endforeach;?></table></div></section>
<section class="card workflow-card"><h2>Received paid sales</h2><div class="scroll"><table><tr><th>Serial</th><th>Order ID</th><th>Event</th></tr><?php foreach($sales as $sale):?><tr><td><?=commerceEscape($sale['serial_number'])?></td><td><?=commerceEscape($sale['order_id'])?></td><td><?=commerceEscape($sale['status'])?></td></tr><?php endforeach;?></table></div></section><p>Refresh this page to update the lists. Payment, cancellation and refund checks run again at scan-out. Orders with refunds or multiple units require review.</p></div></div></main>
<script src="/assets/js/workflow-selection.js"></script>
<script>
const action=document.getElementById('action');action.onchange=()=>{document.getElementById('exportFields').hidden=action.value!=='export';document.getElementById('exitFields').hidden=action.value!=='scan-out';};
document.getElementById('commerce').onsubmit=async e=>{e.preventDefault();const button=document.getElementById('submit');button.disabled=true;try{const r=await fetch('/api/commerce/execute.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action:action.value,serial_number:document.getElementById('serial').value,price:document.getElementById('price').value,order_id:document.getElementById('order').value,location_scan:document.getElementById('location').value,direct_costs:document.getElementById('costs').value})});const data=await r.json();if(!r.ok||!data.success)throw new Error(data.message||'Commerce action failed.');document.getElementById('message').textContent=data.message+(data.order_id?'\n'+data.order_id:'');if(data.order_id)document.getElementById('order').value=data.order_id;}catch(e){document.getElementById('message').textContent=e.message;}finally{button.disabled=false;}};
</script><script src="/assets/js/reference-transactions.js"></script></body></html>
